"""本轮冻结单Activity工具。无Workflow循环；每次动作先登记，未知禁止重发。"""
import os,sys,json,pathlib,hashlib,subprocess,shlex,time,urllib.request,fcntl,re
from tool_scope import phone_args,scoped_business,READ
P=pathlib.Path(__file__).resolve().parent;H=pathlib.Path.home()
def read(p):return json.loads(pathlib.Path(p).read_text())
def atomic(p,x):
 p=pathlib.Path(p);p.parent.mkdir(parents=True,exist_ok=True);tmp=p.with_suffix('.tmp');tmp.write_text(json.dumps(x,ensure_ascii=False,indent=2));tmp.chmod(0o600);os.replace(tmp,p)
def envfile(p):
 out={}
 for l in pathlib.Path(p).read_text().splitlines():
  if '=' in l:
   k,v=l.split('=',1)
   try:v=json.loads(v)
   except ValueError:v=v.strip("'\"")
   out[k]=str(v)
 return out
def environment(c):
 e=os.environ.copy();e['DATABASE_URL']=read(H/'.credentials/zenithjoy-db.json')['DATABASE_URL'];e['LEADGEN_FEISHU_CREDENTIALS']=str(H/'.credentials/leadgen-feishu-yuesheng-live.json');e['LEADGEN_SCORE_AUDIT_DIR']=str(P/'model-score-audit')
 for f in ['cecelia-internal.env','openrouter.env','dashscope.env']:e.update(envfile(H/'.credentials'/f))
 return e
def brain(route,body=None):
 e=envfile(H/'.credentials/cecelia-internal.env');token=e.get('BRAIN_INTERNAL_TOKEN') or e.get('CECELIA_INTERNAL_TOKEN')
 req=urllib.request.Request('http://127.0.0.1:5221/api/brain/'+route,data=json.dumps(body).encode() if body is not None else None,headers={'X-Internal-Token':token,'Content-Type':'application/json'})
 with urllib.request.urlopen(req,timeout=20) as r:return json.load(r)
def task_authority(c):
 for key in [c['root_task_id'],c['tasks'][c['assigned_workflow']]['task_id']]:
  x=brain('tasks/'+key);x=x.get('task',x)
  if x['status']!='in_progress' or x['claimed_by']!=c['actor']:raise ValueError('TASK_AUTHORITY')
def ssh(c,args):
 return ['ssh','-o','BatchMode=yes','-o','ControlMaster=no','-o','ControlPath=none','-o','ConnectTimeout=12','-o','ServerAliveInterval=15','-o','ServerAliveCountMax=3','-J',c['ssh_jump'],c['host'],shlex.join([c['phone_controller']]+args)]
def central(c):
 rows=[x for x in brain('device-locks')['locks'] if x['device_name']==c['serial']]
 if len(rows)!=1:raise ValueError('CENTRAL_RECORD')
 return rows[0]
def local(c):
 r=subprocess.run(ssh(c,['--profile',c['profile'],'lock-status']),capture_output=True,text=True,timeout=25)
 if r.returncode:raise ValueError('LOCAL_READ_UNAVAILABLE')
 return dict(re.findall(r'(\w+)=([^\s]+)',r.stdout))
def resource_authority(c,allow_free=False):
 x=central(c);y=local(c)
 from datetime import datetime
 cent=x['locked_by']==c['central_owner'] and datetime.fromisoformat(x['expires_at'].replace('Z','+00:00')).timestamp()>time.time() if x.get('expires_at') else False
 loc=y.get('owner')==c['local_owner'] and y.get('lock')=='held' and y.get('stale')=='false'
 if not ((cent or allow_free and x['locked_by'] is None) and (loc or allow_free and y.get('lock')=='free')):raise ValueError('RESOURCE_AUTHORITY')
 return x,y
def context():
 c=read(P/'context.json');f=os.environ.get('COMMANDER_ACTIVITY_INPUT_FILE');key=os.environ.get('COMMANDER_ACTIVITY_KEY')
 if not f or not key:raise ValueError('ACTIVITY_IDENTITY_REQUIRED')
 current=read(f);i=c['tasks'][c['assigned_workflow']]
 if current['activity_key']!=key or any(current['identity'].get(k)!=i[k] for k in ['task_id','run_id']):raise ValueError('ACTIVITY_SCOPE')
 return c,key

def outreach_recovery(c,kind,args):
 if c['assigned_workflow']!='104':return False
 from outreach104.tool_extension import readonly_recovery
 return readonly_recovery(kind,args)

def invoke(c,key,kind,args):
 if kind in {'outreach','outreach-phone','outreach-proof'}:
  from outreach104.tool_extension import invoke as invoke104
  return invoke104(P,c,key,kind,args,{'environment':environment,'task_authority':task_authority,'resource_authority':resource_authority,'ssh':ssh})
 if kind=='collection-evidence':
  if key!='collection' or c['assigned_workflow']!='102' or len(args)!=1:raise ValueError('COLLECTION_EVIDENCE_SCOPE')
  resource_authority(c)
  return subprocess.run([c['node'],str(P/'collection-evidence/main.mjs')],input=args[0],capture_output=True,text=True,env=environment(c),timeout=90)
 if kind=='collection-readback':
  if key!='collection' or c['assigned_workflow']!='102' or args:raise ValueError('COLLECTION_READBACK_SCOPE')
  resource_authority(c)
  return subprocess.run([c['node'],str(P/'collection-readback.mjs')],input=json.dumps(c),capture_output=True,text=True,env=environment(c),timeout=90)
 if kind=='native-readback':
  if args:raise ValueError('NATIVE_READBACK_TAKES_NO_ARGS')
  return subprocess.run([c['node'],str(P/'native-inspect.mjs')],input=json.dumps(c),capture_output=True,text=True,timeout=45)
 if kind=='phone':
  approved=phone_args(c,key,args);cmd=args[0]
  if key=='qualification' and cmd in {'swipe-evidence','record-start'}:
   history=[read(f).get('binding',{}) for f in (P/'receipts').glob('*.json')]
   if sum(b.get('activity')==key and b.get('kind')=='phone' and b.get('args',[None])[0]==cmd for b in history)>1:raise ValueError('SINGLE_CAPTURE_OR_SEEK_LIMIT')
  if cmd not in READ and cmd not in {'lock-acquire','lock-acquire-new'}:resource_authority(c)
  elif cmd in {'lock-acquire','lock-acquire-new'}:
   x=central(c)
   if x['locked_by']!=c['central_owner']:raise ValueError('CENTRAL_OWNER_REQUIRED')
  return subprocess.run(ssh(c,approved),capture_output=True,text=True,timeout=420)
 if kind=='brain':
  route=args[0];body=json.loads(args[1]) if len(args)>1 else None
  if body is not None:
   allowed=(key=='preflight' and route=='device-locks/acquire') or (key=='cleanup' and route=='device-locks/release')
   if not allowed or body.get('device_name')!=c['serial'] or body.get('locked_by')!=c['central_owner']:raise ValueError('LOCK_WRITE_SCOPE')
   if route.endswith('release'):
    x=central(c)
    if body.get('expected_lease_version')!=x['lease_version']:raise ValueError('LEASE_CAS_REQUIRED')
  elif route!='device-locks':raise ValueError('BRAIN_READ_SCOPE')
  return {'exit_code':0,'data':brain(route,body)}
 if kind=='business':
  i=scoped_business(c,key,json.loads(args[0]))
  if c['assigned_workflow'] in ['101','102']:resource_authority(c)
  return subprocess.run([c['node'],str(P/'business.mjs')],input=json.dumps(i),capture_output=True,text=True,env=environment(c),timeout=420)
 if kind=='metrics':
  if key!='collect_videos':raise ValueError('METRICS_ACTIVITY_SCOPE')
  return subprocess.run([c['node'],str(P/'metrics.mjs')],input=args[0],capture_output=True,text=True,env=environment(c),timeout=20)
 if kind=='qualify':
  if key!='qualification' or len(args)!=2 or args[0] not in c['verification']['102']['video_ids']:raise ValueError('QUALIFICATION_SCOPE')
  resource_authority(c);audio=pathlib.Path(args[1]).resolve()
  if not audio.is_relative_to(P/'native'):raise ValueError('AUDIO_SOURCE_SCOPE')
  return subprocess.run([c['node'],str(P/'qualification/main.mjs')],input=json.dumps({'context':c,'video_id':args[0],'audio':str(audio),'artifact_dir':str(P/'qualification-receipts'/args[0])}),capture_output=True,text=True,env=environment(c),timeout=420)
 if kind=='fetch-native':
  name=args[0];run=c['tasks'][c['assigned_workflow']]['run_tag']
  if not re.fullmatch(re.escape(run)+r'-[A-Za-z0-9_.-]+',name) and not (c['assigned_workflow']=='104' and name==c['local_owner']+'-outward-ledger.jsonl'):raise ValueError('NATIVE_FILE_SCOPE')
  target=P/'native'/name;target.parent.mkdir(exist_ok=True)
  remote=c['native_root']+'/'+name
  incomplete=P/'download-incomplete';incomplete.mkdir(exist_ok=True)
  partial=incomplete/(target.name+'.download-part')
  remaining=(c['cleanup_deadline_ms'] if key=='cleanup' else c['business_deadline_ms'])/1000-time.time()
  transfer_timeout=max(1,min(600 if target.suffix.lower() in {'.mkv','.mp4','.wav'} else 120,remaining))
  r=subprocess.run(['scp','-p','-o','BatchMode=yes','-o','ControlMaster=no','-o','ControlPath=none','-o','ConnectTimeout=12','-o','ServerAliveInterval=15','-o','ServerAliveCountMax=3','-o','ProxyJump='+c['ssh_jump'],c['host']+':'+remote,str(partial)],capture_output=True,text=True,timeout=transfer_timeout)
  if r.returncode:return r
  os.replace(partial,target)
  return {'exit_code':0,'data':{'path':str(target),'sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'mtime':target.stat().st_mtime,'remote_name':name}}
 if kind=='proof':
  if key not in ['collect_videos','qualification']:raise ValueError('PROOF_ACTIVITY_SCOPE')
  proposed=json.loads(args[0]);dest=pathlib.Path(c['verification']['proof_manifest_path']);m=read(dest)
  allowed='filter_evidence' if key=='collect_videos' else 'qualification_evidence'
  if set(proposed)!={allowed}:raise ValueError('PROOF_FIELDS')
  def check_refs(x):
   if isinstance(x,dict):
    if 'path' in x:
     p=pathlib.Path(x['path']);r=p.resolve()
     roots=[P/'native',P/'qualification-receipts',P/'receipts',P/'phone-cli-source.zsh']
     if p.is_symlink() or not any(r==v.resolve() or r.is_relative_to(v.resolve()) for v in roots) or hashlib.sha256(p.read_bytes()).hexdigest()!=x.get('sha256'):raise ValueError('RAW_PROOF_REFERENCE')
    for v in x.values():check_refs(v)
   if isinstance(x,list):
    for v in x:check_refs(v)
  check_refs(proposed);m.update(proposed);atomic(dest,m);return {'exit_code':0,'data':{'proof_manifest':str(dest),'supplied_raw_references':True,'acceptance_not_asserted':True}}
 raise ValueError('TOOL_KIND')

def main():
 c,key=context();kind,name,*args=sys.argv[1:]
 if not re.fullmatch('[A-Za-z0-9_-]{1,100}',name):raise ValueError('ACTION_NAME')
 task_authority(c);deadline=c['cleanup_deadline_ms'] if key=='cleanup' else c['business_deadline_ms']
 if time.time()*1000>=deadline:raise ValueError('ABSOLUTE_DEADLINE')
 root=P/'receipts';root.mkdir(exist_ok=True);action=root/(name+'.json')
 bind={'kind':kind,'args':args,'activity':key,'identity':c['tasks'][c['assigned_workflow']]}
 lock=open(root/'.tool.lock','a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 if action.exists():
  prior=read(action)
  if prior['binding']!=bind:raise ValueError('ACTION_IDENTITY_CONFLICT')
  if prior['state']!='terminal':raise ValueError('ACTION_UNKNOWN_NO_REPLAY')
  print(json.dumps(prior,ensure_ascii=False));return prior['result']['exit_code']
 if any(read(p).get('state')=='unknown' for p in root.glob('*.json')) and kind not in {'fetch-native','proof','native-readback'} and not (kind=='phone' and args[0] in READ) and not outreach_recovery(c,kind,args):raise ValueError('PRIOR_ACTION_UNKNOWN')
 started_at=time.time();atomic(action,{'binding':bind,'state':'unknown','started_at':started_at})
 try:
  r=invoke(c,key,kind,args);result=r if isinstance(r,dict) else {'exit_code':r.returncode,'stdout':r.stdout,'stderr':r.stderr}
 except subprocess.TimeoutExpired as e:
  if kind!='fetch-native':raise ValueError('TOOL_TIMEOUT_UNKNOWN')
  # subprocess.run kills and waits for this local read-only downloader on timeout.
  # No device mutation ran; a partial local file is never a usable artifact.
  tail=lambda v:(v.decode('utf-8',errors='replace') if isinstance(v,bytes) else v or '')[-2000:]
  result={'exit_code':124,'error':'READ_ONLY_DOWNLOAD_TIMEOUT','artifact_usable':False,'stdout':tail(e.stdout),'stderr':tail(e.stderr),'timeout_seconds':e.timeout}
 except OSError as e:
  if kind!='fetch-native':raise
  result={'exit_code':74,'error':'READ_ONLY_DOWNLOAD_IO_ERROR','artifact_usable':False,'error_type':type(e).__name__}
 except Exception as e:
  # A policy error before launching an operation has no external operation in flight.
  if isinstance(e,ValueError):atomic(action,{'binding':bind,'state':'terminal','started_at':started_at,'result':{'exit_code':2,'error':str(e)},'ended_at':time.time()})
  raise
 out={'binding':bind,'state':'terminal','started_at':started_at,'result':result,'ended_at':time.time()};atomic(action,out)
 encoded=json.dumps(out,ensure_ascii=False)
 print(encoded if len(encoded)<12000 else json.dumps({'state':'terminal','exit_code':result['exit_code'],'receipt':str(action),'large_result_saved':True,'stdout_preview':result.get('stdout','')[:1800],'stderr':result.get('stderr','')[-1200:]},ensure_ascii=False))
 return result['exit_code']
if __name__=='__main__':
 try:sys.exit(main())
 except Exception as e:print(json.dumps({'error':str(e) if isinstance(e,ValueError) else type(e).__name__}),file=sys.stderr);sys.exit(2)

