"""仅104父工具扩展；导入者传固定P与本机函数，模型没有依赖注入入口。"""
import json,pathlib,hashlib,subprocess,datetime,os
from .phone_guard import send_once,need,durable
OPS={'preflight':{'inspect','readback'},'send_dm':{'claim','prepare','readback'},'write_back':{'write_back','readback'},'cleanup':{'readback'}}
RAW={'preflight':{'sender_account','device_preflight','risk_receipt','risk_ui'},'native':{'sender_account','target_profile','typed','sent','risk','send_foreground','risk_foreground','before_screenshot','after_screenshot','ledger'}}
def load(p):return json.loads(pathlib.Path(p).read_text())
def asset(p):return {'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
def cli(P,c,key,obj,parent):
 need(c['assigned_workflow']=='104' and set(obj)=={'op'} and obj['op'] in OPS.get(key,set()),'OUTREACH_OP_SCOPE')
 return subprocess.run([c['node'],str(P/'outreach104/outreach-cli.mjs')],input=json.dumps(obj),capture_output=True,text=True,env=parent['environment'](c),timeout=420)
def receipt_envelope(P,c,a,field):
 p=pathlib.Path(a['path']);r=load(p);b=r.get('binding',{});t=c['tasks']['104']
 allowed={'sender_account':{'account-current'},'device_preflight':{'preflight'},'risk_receipt':{'ui-evidence'}}
 need(p.resolve().parent==(P/'receipts').resolve() and b.get('kind')=='phone' and b.get('args',[None])[0] in allowed[field] and all(b.get('identity',{}).get(k)==t[k] for k in ['task_id','run_id','run_tag']),'RECEIPT_SOURCE')
 need(r.get('state')=='terminal' and isinstance(r.get('started_at'),(int,float)) and isinstance(r.get('ended_at'),(int,float)),'RECEIPT_TIME_MISSING')
 iso=lambda n:datetime.datetime.fromtimestamp(n,datetime.timezone.utc).isoformat()
 e={**{k:t[k] for k in ['task_id','run_id','run_tag']},**{k:c[k] for k in ['profile','serial']},'started_at':iso(r['started_at']),'finished_at':iso(r['ended_at']),'args':b['args'],'response':r['result'],'source_receipt':a}
 d=P/'outreach-envelopes';d.mkdir(mode=0o700,exist_ok=True);dest=d/(p.stem+'-'+field+'.json');durable(dest,e);return asset(dest)
def register_proof(P,c,key,obj):
 need(c['assigned_workflow']=='104' and len(obj)==1 and next(iter(obj)) in RAW,'PROOF_FIELDS');group=next(iter(obj));values=obj[group]
 need(group=='preflight' and key in {'preflight','send_dm'} or group=='native' and key in {'send_dm','write_back'},'PROOF_ACTIVITY')
 need(isinstance(values,dict) and set(values)<=RAW[group] and set(values)>=RAW[group]-{'ledger'},'PROOF_ASSETS')
 result={}
 for k,a in values.items():
  need(isinstance(a,dict) and set(a)=={'path','sha256'},'PROOF_ASSET_FIELDS');p=pathlib.Path(a['path']);real=p.resolve()
  need(p.is_absolute() and p.is_file() and not p.is_symlink() and any(real.is_relative_to((P/d).resolve()) for d in ['receipts','native']),'PROOF_PATH')
  need(hashlib.sha256(p.read_bytes()).hexdigest()==a['sha256'],'PROOF_HASH')
  if k in {'sender_account','device_preflight','risk_receipt'}:result[k]=receipt_envelope(P,c,a,k)
  else:
   need(real.parent==(P/'native').resolve() and p.name.startswith(c['tasks']['104']['run_tag']+'-') or k=='ledger' and real.parent==(P/'native').resolve() and p.name==c['local_owner']+'-outward-ledger.jsonl','NATIVE_PROOF_SCOPE');result[k]=a
 if group=='native':
  inv=P/'outreach-receipts/phone-invocation.json';need(inv.is_file() and not inv.is_symlink(),'INVOCATION_MISSING');result['invocation']=asset(inv)
 dest=P/'outreach-proof.json';proof=load(dest) if dest.exists() else {};proof[group]=result;durable(dest,proof)
 return {'exit_code':0,'data':{'proof':asset(dest),'group':group,'references':len(result)}}
def readonly_recovery(kind,args):
 if kind=='outreach-proof':return True
 if kind!='outreach' or len(args)!=1:return False
 try:return json.loads(args[0])=={'op':'readback'}
 except (ValueError,TypeError):return False
def invoke(P,c,key,kind,args,parent):
 P=pathlib.Path(P).resolve();need(c['assigned_workflow']=='104','WORKFLOW_SCOPE')
 if kind=='outreach':
  need(len(args)==1,'OUTREACH_ARGS');obj=json.loads(args[0])
  if obj.get('op') in {'claim','prepare'}:parent['resource_authority'](c)
  return cli(P,c,key,obj,parent)
 if kind=='outreach-proof':need(len(args)==1,'PROOF_ARGS');return register_proof(P,c,key,json.loads(args[0]))
 if kind=='outreach-phone':
  def readback(_c):
   r=cli(P,c,key,{'op':'readback'},parent);need(r.returncode==0,'PREPARED_GET_FAILED');return json.loads(r.stdout)
  return send_once(P,c,key,args,{**parent,'readback':readback,'run':subprocess.run})
 raise ValueError('OUTREACH_KIND')

