import fs from 'node:fs';import path from 'node:path';
import {createRuntimeDeps} from './runtime-deps.mjs';import {need,txt,hash,asset,save} from './io.mjs';
/** 清理用独立GET；不要求业务公司快照仍可用，不改原订单、不释放prepared。 */
export async function verifyPreservedOrder({context,scope,artifact_dir},injectedDeps){
 const c={...context,sender_id:context.sender_id??context.account};const journal=path.join(artifact_dir,'action.json');
 if(!fs.existsSync(journal))return {verified:true,status:'no_action_journal',note:'仅证明本artifact_dir未发起原订单写入；设备清理由父verifyCleanup独立核验'};
 const j=JSON.parse(fs.readFileSync(journal));need(j.scope.task_id===c.tasks['104'].task_id&&j.scope.run_id===c.tasks['104'].run_id&&j.scope.record_id===scope.record_id,'PRESERVATION_SCOPE');
 const deps=injectedDeps||await createRuntimeDeps(c,scope);
 try{return await deps.withLock(async()=>{
  const row=await deps.api.get(scope.record_id),f=row?.fields||{};
  const identity=row?.record_id===scope.record_id&&txt(f['抖音号']).toLowerCase()===j.scope.target_douyin_id.toLowerCase()&&txt(f['主页链接'])===j.scope.profile_url&&txt(f['实际分发号'])===`${j.scope.profile}(${j.scope.sender_id})`&&hash(txt(f['话术内容']))===j.scope.message_sha256;
  const mark=txt(f['回复结果']),suffix=':'+j.scope.run_tag+':'+j.scope.source+']';
  const protectedRequired=j.reserved_budget===1||fs.existsSync(path.join(artifact_dir,'phone-invocation.json'));
  const protectedPresent=['prepared','sent','restricted','rate_limited'].some(k=>mark.startsWith('[104 '+k+suffix));
  const verified=identity&&protectedRequired&&protectedPresent;
  const out={verified,prepared_or_result_preserved:protectedPresent,protected_required:protectedRequired,unprepared_claim_retained:identity&&!protectedRequired,note:!protectedRequired?'未prepared的claim仍保留；不冒充已释放业务占位':'prepared或原真实终态必须保留；本检查不碰手机',record:row,model_call_count:0};
  const file=path.join(artifact_dir,'cleanup-order-get.json');save(file,out);return {...out,record:undefined,evidence:asset(file)};
 });}finally{await deps.close?.();}
}

