"""父 tools 固定调用；不接受模型传递依赖/发送参数，不执行任何自动补发。"""
import os,json,pathlib,time,datetime,hashlib,base64

def need(value,code):
 if not value:raise ValueError(code)
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def durable(p,obj,exclusive=False):
 raw=(json.dumps(obj,ensure_ascii=False,indent=2)+'\n').encode();target=p if exclusive else p.with_suffix('.updating')
 fd=os.open(target,os.O_WRONLY|os.O_CREAT|(os.O_EXCL if exclusive else os.O_TRUNC),0o600)
 try:os.write(fd,raw);os.fsync(fd)
 finally:os.close(fd)
 if not exclusive:os.replace(target,p)
 fd=os.open(p.parent,os.O_RDONLY)
 try:os.fsync(fd)
 finally:os.close(fd)
def read(p):
 need(not p.is_symlink() and p.is_file(),'GUARD_FILE');return json.loads(p.read_text())
def send_once(root,c,key,args,api):
 # api仅父Python代码闭包，CLI没有注入入口；父持有整次 tool flock。
 need(c.get('assigned_workflow')=='104' and key=='send_dm' and args==[],'PHONE_GUARD_SCOPE')
 d=pathlib.Path(root).resolve()/'outreach-receipts';p=d/'phone-invocation.json';need(not p.exists(),'INVOCATION_EXISTS')
 need(time.time()*1000+420000<c['cleanup_deadline_ms'] and time.time()*1000<c['business_deadline_ms'],'SEND_TIME_BUDGET')
 i=read(d/'send-input.json');s=c['verification']['104'];t=c['tasks']['104']
 expected={**{k:t[k] for k in ['task_id','run_id','run_tag']},**{k:c[k] for k in ['profile','serial']},'sender_id':c.get('sender_id',c.get('account')),**{k:s[k] for k in ['record_id','comment_id','target_douyin_id','profile_url']}}
 need(all(i.get(k)==v for k,v in expected.items()),'SEND_INPUT_SCOPE');msg=i['message']
 need(hashlib.sha256(msg.encode()).hexdigest()==i['message_sha256'] and base64.b64encode(msg.encode()).decode()==i['message_b64'] and i['evidence_id']==t['run_tag']+'-a2-dm-1','SEND_INPUT_HASH')
 runtime=read(d/'prepare-runtime.json');age=time.time()-datetime.datetime.fromisoformat(runtime['observed_at'].replace('Z','+00:00')).timestamp()
 need(runtime.get('verified') is True and runtime.get('pause') is False and runtime.get('halt') is False and -5<=age<=120,'PREPARE_RUNTIME_STALE')
 api['task_authority'](c);api['resource_authority'](c);back=api['readback'](c)
 need(all(back.get(k) is True for k in ['prepared_verified','sender_verified','target_verified','message_verified','same_uid_clear','initial_phone_allowed']) and back.get('phone_invocation_present') is False and back.get('action_key')==i['action_key'],'PREPARED_READBACK')
 api['task_authority'](c);api['resource_authority'](c)
 need(time.time()*1000<c['business_deadline_ms'] and time.time()-datetime.datetime.fromisoformat(runtime['observed_at'].replace('Z','+00:00')).timestamp()<=120,'SEND_TIME_BUDGET')
 command=['private-message-send',i['sender_id'],i['target_douyin_id'],i['message_b64'],i['evidence_id'],i['profile_url']]
 inv={**expected,'schema':'leadgen104-native-invocation-v1','action_key':i['action_key'],'message_sha256':i['message_sha256'],'state':'started','method':'private-message-send','composite_invocations':1,'tap_invocations':0,'evidence_id':i['evidence_id'],'composite_args':command,'started_at':now()}
 try:durable(p,inv,exclusive=True)
 except FileExistsError:raise ValueError('INVOCATION_EXISTS')
 try:
  result=api['run'](api['ssh'](c,['--profile',c['profile']]+command),capture_output=True,text=True,timeout=420)
  inv.update(state='returned',finished_at=now(),response={'exit_code':result.returncode,'stdout':result.stdout,'stderr':result.stderr});durable(p,inv)
 except BaseException as err:
  inv.update(state='unknown',observed_at=now(),error_type=type(err).__name__);durable(p,inv)
  if isinstance(err,ValueError):raise RuntimeError('PHONE_INVOCATION_UNKNOWN') from err
  raise
 return {'exit_code':result.returncode,'data':{'invocation':{'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()},'state':inv['state'],'phone_invocations':1,'send_outcome':'awaiting_native_checker'}}

