"""104原件独立核验；只读文件，不调用手机或服务。"""
import json,sys,pathlib,hashlib,re,datetime,base64,xml.etree.ElementTree as ET
PKG='com.ss.android.ugc.aweme'
def need(x,code):
 if not x:raise ValueError(code)
def asset(a):
 p=pathlib.Path(a['path']);need(p.is_absolute() and p.is_file() and not p.is_symlink(),'ASSET_PATH')
 b=p.read_bytes();need(len(b)<=30*1024*1024 and hashlib.sha256(b).hexdigest()==a['sha256'],'ASSET_HASH');return b
def obj(a):return json.loads(asset(a))
def nodes(a):
 r=ET.fromstring(asset(a));need(r.tag=='hierarchy','XML_ROOT');n=list(r.iter('node'));need(n and any(x.get('package')==PKG for x in n),'XML_PACKAGE');return n
def texts(ns):return [s for n in ns for s in [n.get('text',''),n.get('content-desc','')] if s]
def value(n):return n.get('text') or n.get('content-desc') or ''
def isinput(n):return n.get('class')=='android.widget.EditText'
def bubbles(ns,msg):return [n for n in ns if not isinput(n) and (n.get('text')==msg or n.get('content-desc')==msg)]
def risk(ns):
 ts=texts(ns)
 for kind,words in [('rate_limited',['给陌生人发送消息过于频繁','今日私信次数','消息已达上限','发送频繁','频繁发送']),('restricted',['暂无法给对方','仅互关','仅和他互关','对方设置了']),('unknown',['发送失败'])]:
  hits=[w for w in words if any(w in t for t in ts)]
  if hits:return kind,hits
 if any('互相关注' in t and '发送消息' in t for t in ts):return 'restricted',['互相关注后才能发送消息']
 return 'clear',[]
def millis(x):
 if isinstance(x,(int,float)):return int(x)
 return int(datetime.datetime.fromisoformat(x.replace('Z','+00:00')).timestamp()*1000)
def fields(text):
 out={}
 for line in text.splitlines():
  if '=' in line:
   k,v=line.split('=',1)
   if re.fullmatch(r'[a-zA-Z_][a-zA-Z0-9_]*',k):
    need(k not in out or out[k]==v,'DUPLICATE_NATIVE_FIELD');out[k]=v
 return out
def response(r):return r.get('response',r)
def receipt(a,s,fresh=False):
 r=obj(a);need(all(r.get(k)==s[k] for k in ['task_id','run_id','profile','serial']),'NATIVE_RECEIPT_SCOPE')
 start=millis(r['started_at']);end=millis(r['finished_at']);need(end>=start,'NATIVE_RECEIPT_TIME')
 if fresh:
  now=int(datetime.datetime.now(datetime.timezone.utc).timestamp()*1000);need(-5000<=now-end<=120000,'PREFLIGHT_STALE')
 v=response(r);need(v.get('exit_code',v.get('code'))==0,'NATIVE_RECEIPT_FAILED');return r,fields(v.get('stdout',''))
def preflight(q):
 s=q['scope'];e=q['evidence'];r,account=receipt(e['sender_account'],s,True);_,device=receipt(e['device_preflight'],s,True)
 need(account.get('douyin_id')==s['sender_id'],'SENDER_MISMATCH')
 need(device.get('profile')==s['profile'] and device.get('serial')==s['serial'] and device.get('state')=='device' and device.get('call_state')=='idle','DEVICE_NOT_READY')
 ui,ui_fields=receipt(e['risk_receipt'],s,True);stdout=response(ui).get('stdout','').strip();raw_path=ui_fields.get('ui_evidence') or (stdout.splitlines()[-1] if stdout else '');need(pathlib.Path(raw_path).is_absolute() and pathlib.Path(raw_path).name==pathlib.Path(e['risk_ui']['path']).name,'RISK_XML_RECEIPT_BINDING');ui_nodes=nodes(e['risk_ui']);kind,hits=risk(ui_nodes)
 need(kind=='clear','VISIBLE_PLATFORM_RISK')
 return {'verified':True,'scope':'fresh当前原生账号/设备/可见风险，无预测平台未来行为','risk':'clear','model_call_count':0}
def native(q):
 s=q['scope'];e=q['evidence'];msg=q['message'];key=q['action_key'];inv=obj(e['invocation'])
 need(pathlib.Path(e['invocation']['path']).resolve()==pathlib.Path(q['artifact_dir'],'phone-invocation.json').resolve(),'INVOCATION_PATH')
 need(inv.get('schema')=='leadgen104-native-invocation-v1' and inv.get('action_key')==key,'INVOCATION_KEY')
 for k in ['task_id','run_id','run_tag','profile','serial','sender_id','target_douyin_id','message_sha256','record_id','comment_id','profile_url']:need(inv.get(k)==s[k],'INVOCATION_SCOPE')
 need(inv.get('state')=='returned' and inv.get('composite_invocations')==1,'INVOCATION_UNCONFIRMED')
 start=millis(inv['started_at']);end=millis(inv['finished_at']);need(end>=start and start<=q['business_deadline_ms'] and end<=q.get('cleanup_deadline_ms',q['business_deadline_ms']),'INVOCATION_TIME')
 expected_args=['private-message-send',s['sender_id'],s['target_douyin_id'],base64.b64encode(msg.encode()).decode(),inv.get('evidence_id'),s['profile_url']]
 need(isinstance(inv.get('evidence_id'),str) and inv['evidence_id'].startswith(s['run_tag']+'-') and inv.get('composite_args')==expected_args,'COMPOSITE_ARGUMENTS')
 _,account=receipt(e['sender_account'],s);need(account.get('douyin_id')==s['sender_id'],'SENDER_MISMATCH')
 profile=nodes(e['target_profile']);pattern=r'(?:抖音号|抖音ID)\s*[:：]?\s*'+re.escape(s['target_douyin_id'])+r'(?![A-Za-z0-9_.-])'
 need(any(re.search(pattern,t,re.I) for t in texts(profile)),'TARGET_UID_UNVERIFIED')
 before=nodes(e['typed']);after=nodes(e['sent']);late=nodes(e['risk']);inputs=[n for n in before if isinput(n) and n.get('resource-id')==PKG+':id/msg_et']
 need(len(inputs)==1 and value(inputs[0])==msg and not bubbles(before,msg),'TYPED_OR_OLD_BUBBLE')
 need(hashlib.sha256(msg.encode()).hexdigest()==s['message_sha256'],'MESSAGE_HASH')
