export const coverage=JSON.parse(fs.readFileSync(new URL('./coverage.json',import.meta.url)));
const hostContextExtensions=new Set(['action_id','attempt','remaining_duration_s','budget']);
const predecessorOutputKeys={
 preflight:['ready','business_identity','action_key','order_state_sha256','runtime','native','read_only','model_call_count'],
 send_dm:['status','send_verified','platform_blocked','delivery_verified','business_identity','action_key','order_status','order_state_sha256','native','read_only','model_call_count'],
 write_back:['status','send_verified','platform_blocked','delivery_verified','business_identity','action_key','order_status','order_state_sha256','native','read_only','model_call_count'],
};
const predecessors={preflight:[],send_dm:['preflight'],write_back:['preflight','send_dm'],cleanup:['preflight','send_dm','write_back']};
function matchesFrozenContext(frozen,observed,activity){
 if(!observed||typeof observed!=='object'||Array.isArray(observed))return false;
 const projected={},allowedOutputs=new Set((predecessors[activity]||[]).flatMap(key=>predecessorOutputKeys[key]));
 for(const key of Object.keys(observed)){
  if(Object.hasOwn(frozen,key))projected[key]=observed[key];
  else if(key==='recovery_mode'){if(observed[key]!=='readback_only')return false;}
  else if(!hostContextExtensions.has(key)&&!allowedOutputs.has(key))return false;
 }
 return canonical(projected)===canonical(frozen);
}
const mutableReadbacks=new Set(['inspection-inspect.json','readback.json','cleanup-order-get.json']);
function withoutObservationTime(value){const {observed_at,...business}=value;return business;}
function retainReadback(ref,args,name){
 if(!ref)return {reference:ref,state_sha256:null};
 const source=path.join(args.artifact_dir,name);
 need(mutableReadbacks.has(name)&&ref.path===source&&fs.realpathSync(args.artifact_dir)===args.artifact_dir,'READBACK_SOURCE_PATH');
 const fd=fs.openSync(source,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let raw;
 try{const st=fs.fstatSync(fd);need(st.isFile()&&st.size<=30*1024*1024,'READBACK_SOURCE_TYPE');raw=fs.readFileSync(fd);}finally{fs.closeSync(fd);}
 const sha=hash(raw);need(sha===ref.sha256,'READBACK_SOURCE_HASH');
 const document=JSON.parse(raw),state_sha256=hash(canonical(withoutObservationTime(document)));
 const directory=path.join(args.artifact_dir,'checker-evidence');privateDir(directory);const file=path.join(directory,sha+'.json');
 let out;
 try{out=fs.openSync(file,'wx',0o400);}catch(e){if(e.code!=='EEXIST')throw e;}
 if(out!==undefined){try{fs.writeFileSync(out,raw);fs.fsyncSync(out);}finally{fs.closeSync(out);}const dir=fs.openSync(directory,'r');try{fs.fsyncSync(dir);}finally{fs.closeSync(dir);}}
 const saved=fs.openSync(file,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);
 try{need(fs.fstatSync(saved).isFile()&&hash(fs.readFileSync(saved))===sha,'READBACK_SNAPSHOT_HASH');}finally{fs.closeSync(saved);}
 return {reference:{path:file,sha256:sha},state_sha256};
}
function selected(value,keys){return Object.fromEntries(keys.filter(k=>Object.hasOwn(value,k)).map(k=>[k,value[k]]));}
