 try{
  need(q.phase==='end'&&q.workflow==='104'&&coverage[q.activity],'CHECKER_SCOPE');const expected=coverage[q.activity].checks;need(canonical(q.checks)===canonical(expected),'CHECK_COVERAGE');
  const args=resolveInput(root,q.activity,{op:'readback'}),c=args.context;need(matchesFrozenContext(c,q.context,q.activity)&&['task_id','run_id','run_tag'].every(k=>q[k]===c.tasks['104'][k]),'CHECKER_IDENTITY');
