  const business_identity=hash(canonical({task:c.tasks['104'],company_id:c.company_id,tenant_id:c.tenant_id,scope:args.scope}));
  if(q.activity==='cleanup'){
   const r=await d.cleanup({...q,checks:expected.filter(x=>x!=='original_order_preserved')});checks.push(...r.checks);const p=await d.preserved(),saved=retainReadback(p.evidence,args,'cleanup-order-get.json');if(p.evidence)p.evidence=saved.reference;add('original_order_preserved',p.verified,p);output={...r.output,business_identity,prepared_preservation:{...selected(p,['verified','status','prepared_or_result_preserved','protected_required','unprepared_claim_retained']),order_state_sha256:saved.state_sha256}};
  }else if(q.activity==='preflight'){
   const r=await d.order('inspect'),saved=retainReadback(r.inspection,args,'inspection-inspect.json');r.inspection=saved.reference;for(const id of expected)add(id,r.status==='ready',{inspection:r.inspection,runtime:r.runtime,native:r.native,status:r.status});output={ready:r.status==='ready',business_identity,action_key:r.action_key,order_state_sha256:saved.state_sha256,runtime:r.runtime?withoutObservationTime(r.runtime):null,native:r.native};
  }else{
   const r=await d.order('readback'),saved=retainReadback(r.original_order,args,'readback.json');r.original_order=saved.reference;const n=await d.native();const identityOK=r.sender_verified&&r.target_verified&&r.message_verified&&r.same_uid_clear;const nativeOK=n.verified===true&&['sent','restricted','rate_limited'].includes(n.outcome);
   if(q.activity==='send_dm'){
    add('original_order_prepared',r.prepared_verified&&r.status==='prepared',r.original_order);add('exact_action_identity',identityOK,{action_key:r.action_key});add('single_native_attempt',nativeOK&&n.actual_send_attempts===1,n);add('native_send_outcome',nativeOK,n);
   }else{
    add('native_result_verified',nativeOK,n);add('original_order_writeback',identityOK&&nativeOK&&r.status===n.outcome,r.original_order);
    const j=JSON.parse(fs.readFileSync(path.join(args.artifact_dir,'action.json'))),v=j.terminal_fields?.['触达时间'];const millis=typeof v==='number'?v:Date.parse(v);
    add('accurate_contact_time',nativeOK&&millis===n.sent_at_ms,{timestamp_basis:n.timestamp_basis,sent_at_ms:n.sent_at_ms});add('delivery_not_inferred',n.delivery_verified===false&&n.read_verified===false,{delivery_verified:n.delivery_verified,read_verified:n.read_verified});
   }
   output={status:n.outcome||'unknown',send_verified:nativeOK&&n.outcome==='sent',platform_blocked:nativeOK&&n.outcome!=='sent',delivery_verified:false,business_identity,action_key:r.action_key,order_status:r.status,order_state_sha256:saved.state_sha256,native:selected(n,['verified','outcome','sent_at_ms','timestamp_basis','message_delta_verified','same_uid_verified','actual_send_attempts','delivery_verified','read_verified'])};
  }
 }catch(e){for(const id of q.checks||[])if(!checks.some(x=>x.id===id))add(id,null,{error:/^[A-Z_]+$/.test(e.message)?e.message:'READBACK_UNAVAILABLE'});output={...output,readback_error:true};}
 const all=!output.readback_error&&checks.length===(q.checks||[]).length&&checks.length>0&&checks.every(x=>x.status==='passed');
 return {identity,nonce:q.nonce,checks,outcome:all?'passed':'blocked',output:{...output,read_only:true,model_call_count:0}};
}

