  child.once('error',()=>finish(Error('M4_READ_FAILED')));
  child.once('close',code=>{
   if(settled)return;if(code!==0)return finish(Error('M4_READ_FAILED'));
   try{finish(null,JSON.parse(out));}catch{finish(Error('M4_READ_INVALID'));}
  });
  try{child.stdin.end(JSON.stringify({profile:c.profile,serial:c.serial,local_owner:c.local_owner}));}catch{finish(Error('M4_READ_FAILED'));}
 });
}
