 return {authorize,qualify,api,withLock:fn=>orders.withOrderLock(c.line,fn,{directory:LOCK_DIR}),validateOriginal:r=>bridge.fieldsMatch(outbox,r)&&lib.classifyPending(r.fields)==='ok'&&lib.gradeAllowed(lib.leadGrade(r.fields),route.outreachGrades),
