import fs from 'node:fs';import path from 'node:path';
import {hash,canonical,need,txt,save,asset,privateDir} from './io.mjs';
import {acquireProcessLock} from './process-lock.mjs';
import {createRuntimeDeps} from './runtime-deps.mjs';
const OPS=new Set(['inspect','claim','prepare','readback','write_back']);
const reserved=r=>['触达中','已触达'].includes(txt(r.fields?.['状态']))||/^\[104 (?:prepared|sent|restricted|rate_limited|unknown):/.test(txt(r.fields?.['回复结果']));
const equalFields=(r,f)=>Object.entries(f).every(([k,v])=>txt(r.fields?.[k])===String(v));
function timeValue(types,ms){need(Number.isSafeInteger(ms)&&ms>0,'SEND_TIME_UNVERIFIED');const f=types.find(f=>f.field_name==='触达时间');need(f,'CONTACT_TIME_FIELD_MISSING');if(f.type===5)return ms;need(f.type===1,'CONTACT_TIME_FIELD_TYPE');return new Date(ms).toISOString();}
function validateOptions(types,fields){for(const [k,v] of Object.entries(fields)){const f=types.find(f=>f.field_name===k);if(f?.type===3)need(f.property?.options?.some(o=>o.name===v),'FIELD_OPTION_UNSUPPORTED');}}
/** 仅原订单5操作；无手机调用，无新发送循环。 */
export async function request({op,context:c,scope:s,artifact_dir,evidence:e={}},injectedDeps){
 c={...c,sender_id:c?.sender_id??c?.account};
 need(OPS.has(op)&&c?.tasks?.['104']&&s?.record_id&&s.comment_id&&s.target_douyin_id&&s.profile_url,'OUTREACH_SCOPE');
 const task=c.tasks['104'],run=task.run_tag,source=c.marker_source||c.source_commit;
 need(/^[A-Za-z0-9_-]{1,64}$/.test(run||'')&&/^[a-f0-9]{40}$/.test(source||''),'MARKER_SCOPE');
 privateDir(artifact_dir);const held=await acquireProcessLock(path.join(artifact_dir,'operation.lock'));let deps;
 try{
  deps=injectedDeps||await createRuntimeDeps(c,s);held.assertHeld();
  const auth=await deps.authorize(op);need(auth.max_new_recipients===1&&auth.max_send_attempts===1&&Number.isSafeInteger(auth.test_execution_daily_cap)&&auth.test_execution_daily_cap>0,'AUTHORIZATION_LIMIT');
  const message=auth.message;need(typeof message==='string'&&message.length>0&&message.length<=600&&!/[\r\n"&<>]/.test(message),'AUTHORIZED_MESSAGE_INVALID');
  const messageSha=hash(message);need(!auth.message_sha256||auth.message_sha256===messageSha,'AUTHORIZED_MESSAGE_HASH');
  const actionScope={task_id:task.task_id,run_id:task.run_id,run_tag:run,source,company_id:c.company_id,tenant_id:c.tenant_id,line:c.line,profile:c.profile,serial:c.serial,sender_id:c.sender_id,record_id:s.record_id,comment_id:s.comment_id,target_douyin_id:s.target_douyin_id,profile_url:s.profile_url,message_sha256:messageSha};
  const actionKey=hash(canonical(actionScope)),journal=path.join(artifact_dir,'action.json');
  let j=fs.existsSync(journal)?JSON.parse(fs.readFileSync(journal)):{schema:'leadgen104-action-v1',action_key:actionKey,scope:actionScope,phase:'new',reserved_budget:0};
  need(j.action_key===actionKey&&canonical(j.scope)===canonical(actionScope),'ACTION_SCOPE_CHANGED');
  const flush=()=>save(journal,j);
  const recoverSendInput=()=>{if(j.phase!=='prepared'||j.reserved_budget!==1||!j.last_get||fs.existsSync(path.join(artifact_dir,'phone-invocation.json')))return;const p=path.join(artifact_dir,'send-input.json');const input={schema:'leadgen104-send-input-v1',action_key:actionKey,...actionScope,message,message_b64:Buffer.from(message).toString('base64'),evidence_id:run+'-a2-dm-1',profile_url:s.profile_url};if(fs.existsSync(p))need(canonical(JSON.parse(fs.readFileSync(p)))===canonical(input),'SEND_INPUT_CHANGED');else save(p,input);};
  const marker=k=>`[104 ${k}:${run}:${source}]`;
  const claimFields={'状态':'触达中','话术ID':'task-'+task.task_id,'话术版本':'task-authorized','话术内容':message,'实际分发号':`${c.profile}(${c.sender_id})`,'回复结果':marker('claim')};
  const expectedPrepared={...claimFields,'回复结果':marker('prepared')};
  const identity=r=>r?.record_id===s.record_id&&txt(r.fields?.['抖音号']).toLowerCase()===s.target_douyin_id.toLowerCase()&&txt(r.fields?.['主页链接'])===s.profile_url;
  const output=(status,r,extra={})=>({status,action_key:actionKey,scope_digest:actionKey,prepared_verified:identity(r)&&equalFields(r,expectedPrepared),sender_verified:txt(r?.fields?.['实际分发号'])===claimFields['实际分发号'],target_verified:identity(r),message_verified:hash(txt(r?.fields?.['话术内容']))===messageSha,phone_invocation_present:fs.existsSync(path.join(artifact_dir,'phone-invocation.json')),initial_phone_allowed:j.phase==='prepared'&&Boolean(j.last_get)&&fs.existsSync(path.join(artifact_dir,'send-input.json'))&&!fs.existsSync(path.join(artifact_dir,'phone-invocation.json'))&&identity(r)&&equalFields(r,expectedPrepared),phone_permission:'父工具必须独占创建phone-invocation.json；本返回不产生重复发送许可',...(fs.existsSync(journal)?{journal:asset(journal)}:{}),...extra});
  return await deps.withLock(async()=>{
   held.assertHeld();await deps.authorize(op);const qualification=await deps.qualify();need(qualification?.verified,'QUALIFICATION_UNVERIFIED');
   let all=await deps.api.all(),row=all.find(r=>r.record_id===s.record_id);need(all.filter(r=>r.record_id===s.record_id).length===1&&identity(row),'ORIGINAL_ORDER_IDENTITY');
   need(!deps.validateStable||deps.validateStable(row),'ORIGINAL_STABLE_FIELDS_CHANGED');
   const others=all.filter(r=>r.record_id!==s.record_id&&txt(r.fields?.['抖音号']).toLowerCase()===s.target_douyin_id.toLowerCase());
   const inspectFile=path.join(artifact_dir,'inspection-'+op+'.json');save(inspectFile,{observed_at:new Date().toISOString(),action_key:actionKey,qualification,order:row,same_uid_orders:others});
   if(op==='inspect'){
    const runtime=await deps.freshRuntime(all),native=await deps.checkPreflight(e,actionScope,auth);
    const ready=others.every(r=>!reserved(r))&&deps.validateOriginal(row)&&txt(row.fields['状态'])==='待触达'&&txt(row.fields['发送状态'])==='未发送';
    return output(ready&&runtime.verified&&runtime.pause===false&&runtime.halt===false&&runtime.today_dm_attempts<auth.test_execution_daily_cap&&runtime.today_sent_orders<auth.test_execution_daily_cap&&native.verified?'ready':'blocked',row,{inspection:asset(inspectFile),runtime,native});
   }
   if(op==='readback'){
    const f=path.join(artifact_dir,'readback.json');row=await deps.api.get(s.record_id);need(identity(row)&&(!deps.validateStable||deps.validateStable(row)),'ORIGINAL_ORDER_IDENTITY');save(f,{observed_at:new Date().toISOString(),action_key:actionKey,record:row});
    let status=equalFields(row,expectedPrepared)?'prepared':equalFields(row,claimFields)?'claimed':'unknown';
    if(j.terminal_fields&&equalFields(row,j.terminal_fields))status=j.terminal_outcome;
    return output(status,row,{original_order:asset(f),other_reserved_count:others.filter(reserved).length,same_uid_clear:!others.some(reserved)});
   }
   need(!others.some(reserved),'RECIPIENT_RESERVED');
   need(!all.some(r=>r.record_id!==s.record_id&&txt(r.fields?.['话术ID'])===claimFields['话术ID']&&reserved(r)),'AUTHORIZATION_ALREADY_RESERVED');
   async function putAndRead(fields,phase){
    validateOptions(await deps.api.fields(),fields);j.pending_write={fields,phase};j.phase=phase+'_intent';flush();held.assertHeld();await deps.authorize(op);need((await deps.qualify())?.verified,'QUALIFICATION_UNVERIFIED');
    try{await deps.api.put(s.record_id,fields);}catch{/* 永不盲重试；读取原行判断是否已生效。 */}
    try{row=await deps.api.get(s.record_id);}catch{return false;}
    if(!identity(row)||!equalFields(row,fields)||(deps.validateStable&&!deps.validateStable(row)))return false;
    const f=path.join(artifact_dir,phase+'-get.json');save(f,{observed_at:new Date().toISOString(),action_key:actionKey,record:row});j.phase=phase;j.last_get=asset(f);delete j.pending_write;flush();return true;
   }
   if(j.pending_write){
    row=await deps.api.get(s.record_id);if(identity(row)&&equalFields(row,j.pending_write.fields)){j.phase=j.pending_write.phase;const f=path.join(artifact_dir,j.phase+'-recovered-get.json');save(f,{observed_at:new Date().toISOString(),action_key:actionKey,record:row});j.last_get=asset(f);delete j.pending_write;flush();}else return output('unknown',row,{reason:'PREVIOUS_PUT_UNCONFIRMED'});
   }
   if(op==='claim'){
    if(equalFields(row,expectedPrepared))return output('prepared',row,{read_only_recovery:true});
    if(equalFields(row,claimFields))return output('claimed',row,{read_only_recovery:true});
    need(j.phase==='new'&&txt(row.fields['状态'])==='待触达'&&txt(row.fields['发送状态'])==='未发送'&&deps.validateOriginal(row),'ORDER_NOT_READY');
    return output(await putAndRead(claimFields,'claimed')?'claimed':'unknown',row,{original_order:j.last_get||null});
   }
   if(op==='prepare'){
    const runtime=await deps.freshRuntime(all);save(path.join(artifact_dir,'prepare-runtime.json'),runtime);
    need(runtime.verified&&runtime.pause===false&&runtime.halt===false&&Number.isSafeInteger(runtime.today_dm_attempts)&&runtime.today_dm_attempts<auth.test_execution_daily_cap&&Number.isSafeInteger(runtime.today_sent_orders)&&runtime.today_sent_orders<auth.test_execution_daily_cap,'CURRENT_RUNTIME_BLOCKED');
    const native=await deps.checkPreflight(e,actionScope,auth);need(native.verified,'PREFLIGHT_NATIVE_UNVERIFIED');
    if(equalFields(row,expectedPrepared)){recoverSendInput();return output('prepared',row,{read_only_recovery:true,runtime});}
    need(equalFields(row,claimFields)&&j.phase==='claimed'&&!fs.existsSync(path.join(artifact_dir,'phone-invocation.json')),'PREPARE_NOT_OWN_CLAIM');
    j.reserved_budget=1;flush();const ok=await putAndRead({'回复结果':marker('prepared')},'prepared');
    need(!ok||equalFields(row,expectedPrepared),'PREPARED_FIELDS_CHANGED');
    if(ok){recoverSendInput();return output('prepared',row,{send_input:asset(path.join(artifact_dir,'send-input.json')),original_order:j.last_get,runtime});}
    return output('unknown',row,{reason:'PREPARE_PUT_UNCONFIRMED'});
   }
   const native=await deps.checkNative(e,actionScope,auth,artifact_dir);save(path.join(artifact_dir,'native-check.json'),native);
   if(!native.verified||!['sent','restricted','rate_limited'].includes(native.outcome))return output('unknown',row,{reason:'NATIVE_SEND_UNVERIFIED',native});
   const outcome=native.outcome;
   const fields={'状态':outcome==='sent'?'已触达':'触达受阻','发送状态':outcome==='sent'?'已发送':'发送失败','回复结果':`${marker(outcome)} ${messageSha} ${outcome==='sent'?'送达未证':native.reason||outcome}`,'触达时间':timeValue(await deps.api.fields(),native.sent_at_ms)};
   if(outcome==='sent')fields['成功触达']='待确认';
   if(equalFields(row,{...claimFields,...fields}))return output(outcome,row,{read_only_recovery:true,native});
   need(equalFields(row,expectedPrepared),'WRITEBACK_NOT_OWN_PREPARED');
   j.terminal_fields={...claimFields,...fields};j.terminal_outcome=outcome;flush();
   const ok=await putAndRead(fields,'written');return output(ok?outcome:'unknown',row,{native,original_order:j.last_get||null});
  });
 }finally{try{await deps?.close?.();}finally{await held.release();}}
}

