import hashlib,os,pathlib

def pinned_transport(c):
 out={}
 for key in ['phone_controller','adb_host_config','phone_registry']:
  p=pathlib.Path(c.get(key,''))
  if not p.is_absolute() or p.is_symlink() or not p.is_file() or hashlib.sha256(p.read_bytes()).hexdigest()!=c.get(key+'_sha256'):
   raise ValueError('TRANSPORT_SOURCE_CHANGED')
  out[key]=str(p)
 if not pathlib.Path(out['phone_controller']).resolve().is_relative_to(pathlib.Path(c['runtime_root']).resolve()):raise ValueError('CONTROLLER_SOURCE_SCOPE')
 return out

def local_environment(c):
 p=pinned_transport(c)
 return {**os.environ,'ZJ_ADB_HOST_CONFIG':p['adb_host_config'],'DOUYIN_PHONE_REGISTRY':p['phone_registry']}

def local_command(c,args):
 p=pinned_transport(c)
 return ['/usr/bin/env','ZJ_ADB_HOST_CONFIG='+p['adb_host_config'],'DOUYIN_PHONE_REGISTRY='+p['phone_registry'],p['phone_controller'],*args]

